package cpamp

type ProfileMembership struct {
	Account string `json:"account"`
	Start   int64  `json:"start_ms"`
	End     int64  `json:"end_ms"`
}

// Translate legacy metadata for editing without expanding or truncating its dates.
func profileMemberships(c ProfileConfig, p Profile) []ProfileMembership {
	if p.Memberships != nil {
		return append([]ProfileMembership{}, p.Memberships...)
	}
	out := []ProfileMembership{}
	if p.Selection {
		for _, a := range p.Accounts {
			out = append(out, ProfileMembership{Account: a})
		}
	} else {
		for _, b := range c.Bindings {
			if b.Profile == p.ID {
				out = append(out, ProfileMembership{Account: b.Account, Start: b.Start, End: b.End})
			}
		}
	}
	return out
}
